// Extract search parameters from webhook
const params = $input.first().json;

const userId = params.user_id;
const category = params.category;
const moq = params.moq || 'any';
const priceRange = params.price_range || 'any';

// Build Alibaba search URL
const searchQuery = encodeURIComponent(category);
const alibaba_url = `https://www.alibaba.com/trade/search?SearchText=${searchQuery}`;

// Alternative sources
const sources = [
  {
    name: 'alibaba',
    url: alibaba_url,
    selector: '.organic-list-offer'
  },
  {
    name: '1688',
    url: `https://s.1688.com/selloffer/offer_search.htm?keywords=${searchQuery}`,
    selector: '.sm-offer-item'
  }
];

// Return search configuration
return {
  json: {
    user_id: userId,
    category: category,
    moq: moq,
    price_range: priceRange,
    search_sources: sources,
    timestamp: new Date().toISOString(),
    status: 'initialized'
  }
};

// Aggregate all leads and prepare response
const allLeads = $input.all();

const leadsData = allLeads.map(item => ({
  company_name: item.json.company_name,
  rating: item.json.rating,
  moq: item.json.moq,
  price: item.json.price,
  location: item.json.location,
  years: item.json.years,
  contact_email: item.json.contact_email,
  company_url: item.json.company_url,
  ai_score: item.json.ai_score,
  recommended: item.json.recommended,
  ai_summary: item.json.ai_summary,
  pros: item.json.pros,
  risks: item.json.risks
}));

return {
  json: {
    success: true,
    total_leads: leadsData.length,
    leads: leadsData,
    timestamp: new Date().toISOString()
  }
};
